// Acceptance host for the shared form: dlopen the built library, fetch
// the API table through the single <stem>_get_api entry, and call the
// three contract functions through the table. The header included here
// is the one generated by `sa build-lib` from blib.sai.
#include <dlfcn.h>
#include <stdint.h>
#include <stdio.h>

#include "blib.h"

int main(int argc, char **argv) {
    if (argc != 2) {
        printf("usage: host <path-to-libblib.so>\n");
        return 2;
    }
    void *handle = dlopen(argv[1], RTLD_NOW);
    if (!handle) {
        printf("DLOPEN_FAIL %s\n", dlerror());
        return 1;
    }
    typedef const blib_api *(*get_api_fn)(void);
    get_api_fn get_api = (get_api_fn)dlsym(handle, "blib_get_api");
    if (!get_api) {
        printf("NO_GET_API\n");
        return 1;
    }
    const blib_api *api = get_api();
    printf("abi=%u count=%u\n", api->abi_version, api->entry_count);
    if (api->abi_version != BLIB_ABI_VERSION || api->entry_count != 3) {
        printf("PROBE_MISMATCH header\n");
        return 1;
    }
    int64_t sum = api->bl_add(19, 23);
    printf("add=%lld\n", (long long)sum);
    const uint8_t msg[5] = { 'h', 'e', 'l', 'l', 'o' };
    uint64_t checksum = api->bl_checksum((void *)msg, 5);
    printf("checksum=%llu\n", (unsigned long long)checksum);
    uint64_t out = 0;
    int32_t status = api->bl_answer(&out);
    printf("answer status=%d out=%llu\n", status, (unsigned long long)out);
    if (sum == 42 && checksum == 532 && status == 0 && out == 42) {
        printf("PROBE_OK\n");
        return 0;
    }
    printf("PROBE_MISMATCH values\n");
    return 1;
}
